import{z as s,x as o,o as e,c as l,q as B,j as t,D as E,d as i,s as A,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"波动率套利案例","description":"","frontmatter":{"title":"波动率套利案例","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vt-arbitrage-cases.md","filePath":"quant/vt-arbitrage-cases.md","lastUpdated":1791413859000}'),p={name:"quant/vt-arbitrage-cases.md"};function d(h,a,D,u,c,m){const r=o("Mermaid");return e(),l("div",null,[a[2]||(a[2]=B('<h1 id="波动率套利案例" tabindex="-1">波动率套利案例 <a class="header-anchor" href="#波动率套利案例" aria-label="Permalink to &quot;波动率套利案例&quot;">​</a></h1><div class="epigraph"><p>「波动率套利」里的「套利」二字是营销：清单上的每个案例都在把某种保险卖给需要凸性的人，赔率来自风险价格，不来自错误定价。</p><footer>—— 据 Bakshi and Kapadia, 2003；Driessen, Maenhout and Vilkov, 2009 整理</footer></div><p><a href="/quant/vt-greeks-portfolio">上一课</a>把组合的残差收敛成观点，「预测与工具」单元到此齐备。第二单元「策略与风控」用案例开题：把市场上叫「波动率套利」的策略逐个过堂——信号是什么、溢价谁在付、怎么死、账怎么记。基础课的<a href="/quant/vol-arb">波动率套利</a>已给出恒等式与「指数上买 gamma 平均亏」的事实；本课做案例学与记账学，不再推导。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>案例复盘的共同陷阱有三：把风险溢价误读成错误定价，于是加杠杆去「收敛」；把无条件统计当成条件分布，于是在状态切换月爆仓；把两条腿的溢价记进一个桶，于是归因永远对不上。逐一过案例的意义，是让这三个陷阱在每个策略上有具体的形状。</p><p><span class="marginnote">常见误区：看到「套利」两个字就以为无风险。清单上的每笔交易其实都在卖保险——平时收小额保费，出事时赔付大额。把它当无风险去加杠杆，等于把保费收入当工资、把赔付当意外。</span></p><h3 id="四个案例逐个过" tabindex="-1">四个案例逐个过 <a class="header-anchor" href="#四个案例逐个过" aria-label="Permalink to &quot;四个案例逐个过&quot;">​</a></h3><p>方差 rich/cheap：信号来自<a href="/quant/vt-forecast-competition">预测栈</a>与执行价之差，合同与账目见<a href="/quant/vt-variance-swap-deep">方差互换的深化</a>。溢价是<a href="/quant/variance-risk-premium">方差风险溢价</a>，卖方收 theta、付左尾；崩坏方式是拥挤平仓，记账要点是四栏账不得合并。</p><p>偏度：<a href="/quant/risk-reversal-skew">风险反转</a>无条件买入平均付<a href="/quant/skew-risk-premium">偏度溢价</a>（Kozhan–Neuberger–Schneider 的证据）；条件化后，崩盘刚过、保险最贵时卖出与恐慌未至时买入各有一段可做。崩坏方式是崩盘延续，比回撤预期更深；记账要点是 sticky 惯例下的隐含斜度重估 PnL 单列，不与已实现偏度混算。</p><p>相关：<a href="/quant/dispersion-trade">Dispersion 交易</a>卖出「指数减成分」的隐含相关保险，溢价为正来自共跳保险更贵（<a href="/quant/dispersion-corr-prem">相关溢价</a>，DMV 2009）；崩坏方式是<a href="/quant/correlation-breakdown">相关性崩溃</a>日一次性偿还；记账要点是与偏度在崩盘重叠，两账必须正交化，防止双计。</p><p>期限：<a href="/quant/vix-term-structure-trade">VIX 期限结构</a>的日历陡峭化，卖短端溢价、买长端方差；崩坏方式是倒挂日凸性暴露放大；记账要点是按方差桶且扣除开方凸性。</p><p><span class="marginnote">复盘口径建议三条全报：无条件年化夏普、条件最差月、拥挤度代理（空头未平仓、ETP 规模、成交占比）。只报第一条的案例研究，等于把死因从病历里删掉——<a href="/quant/momentum-crash">动量崩溃</a>的教训原样适用于此。</span></p>',12)),(e(),t(n,null,{default:E(()=>[A(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20F1%5B%22%E6%96%B9%E5%B7%AE%20rich%20%2F%20cheap%22%5D%20--%3E%20P1%5B%22%E6%BA%A2%E4%BB%B7%EF%BC%9A%E6%96%B9%E5%B7%AE%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20F2%5B%22%E5%81%8F%E5%BA%A6%20RR%22%5D%20--%3E%20P2%5B%22%E6%BA%A2%E4%BB%B7%EF%BC%9A%E5%B7%A6%E5%B0%BE%E4%BF%9D%E9%99%A9%E8%B4%B9%22%5D%0A%20%20F3%5B%22%E7%9B%B8%E5%85%B3%20dispersion%22%5D%20--%3E%20P3%5B%22%E6%BA%A2%E4%BB%B7%EF%BC%9A%E5%85%B1%E8%B7%B3%E4%BF%9D%E9%99%A9%E8%B4%B9%22%5D%0A%20%20F4%5B%22%E6%9C%9F%E9%99%90%E6%97%A5%E5%8E%86%22%5D%20--%3E%20P4%5B%22%E6%BA%A2%E4%BB%B7%EF%BC%9A%E7%9F%AD%E7%AB%AF%E5%B1%95%E6%9C%9F%E8%B4%B9%22%5D%0A%20%20P1%20--%3E%20DEAD%5B%22%E5%B4%A9%E5%9D%8F%EF%BC%9A%E6%8B%A5%E6%8C%A4%E4%B8%8E%E4%BD%93%E5%88%B6%E5%88%87%E6%8D%A2%22%5D%0A%20%20P2%20--%3E%20DEAD%0A%20%20P3%20--%3E%20DEAD%0A%20%20P4%20--%3E%20DEAD%0A%20%20DEAD%20--%3E%20ACC%5B%22%E8%AE%B0%E8%B4%A6%EF%BC%9A%E6%BA%A2%E4%BB%B7%E4%B8%8E%E5%B4%A9%E5%9D%8F%E5%88%86%E5%88%97%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>过堂的操作流程固定为四问。一问信号：用什么测量、对齐哪条合同（预测栈对齐条带执行价，而不是对齐 ATM IV）。二问溢价：谁在付、为什么非付不可——付方是持有凸性需求的人：杠杆投资者、发产品的机构、买尾部保险的组合；他们付的是预算内的保险费。三问崩坏：拥挤度怎么测、体制切换的先导指标是什么（市场方差状态、融资利差）。四问记账：溢价、凸性、崩坏三段是否分列，残差是否回到「已知持有」清单。</p><p>四问都答得出，策略才进入可投清单；答不出的一律当「带杠杆的贝塔」处理，仓位按崩坏日损失倒推限额。</p><p><span class="marginnote">术语翻译：「带杠杆的贝塔」意思是——剥掉故事包装后，这策略其实是在借钱买同一个风险因子。四问答不出时，宁可按贝塔的仓位纪律 sizing，也不要按 alpha 的信仰给额度。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>案例背后的共同结构是保险市场：波动率策略的对手盘不是「错的定价」，而是有结构性凸性需求的买方。这解释了两件事。其一，溢价的持续性：只要有人为凸性付钱，卖方溢价就会存在，但它以左尾为代价，无条件夏普必然高估。其二，死法的相似性：溢价吸引资金、资金压低溢价、杠杆补足收益、体制切换一次性清算——四个案例只是在不同维度上重演同一条路径。所以风控的对象不是单个信号，而是这条路径本身：拥挤度与杠杆是先导指标，不是事后注脚。</p>',6)),(e(),t(n,null,{default:E(()=>[A(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20PREM%5B%22%E6%BA%A2%E4%BB%B7%E5%AD%98%E5%9C%A8%3A%E6%9C%89%E4%BA%BA%E4%B8%BA%E5%87%B8%E6%80%A7%E4%BB%98%E9%92%B1%22%5D%20--%3E%20INFLOW%5B%22%E8%B5%84%E9%87%91%E6%B6%8C%E5%85%A5%E5%90%8C%E4%B8%80%E7%AD%96%E7%95%A5%22%5D%0A%20%20INFLOW%20--%3E%20COMPRESS%5B%22%E6%8B%A5%E6%8C%A4%E6%8A%8A%E6%BA%A2%E4%BB%B7%E5%8E%8B%E8%96%84%22%5D%0A%20%20COMPRESS%20--%3E%20LEV%5B%22%E7%94%A8%E6%9D%A0%E6%9D%86%E8%A1%A5%E8%B6%B3%E7%9B%AE%E6%A0%87%E6%94%B6%E7%9B%8A%22%5D%0A%20%20LEV%20--%3E%20SWITCH%5B%22%E4%BD%93%E5%88%B6%E5%88%87%E6%8D%A2%3A%E6%B3%A2%E5%8A%A8%E7%8A%B6%E6%80%81%E8%B7%B3%E5%8F%98%22%5D%0A%20%20SWITCH%20--%3E%20LIQ%5B%22%E5%B7%A6%E5%B0%BE%E4%B8%80%E6%AC%A1%E6%80%A7%E5%85%91%E7%8E%B0%2C%E5%BC%BA%E5%88%B6%E5%B9%B3%E4%BB%93%22%5D%0A%20%20LIQ%20--%3E%7C%22%E5%87%BA%E6%B8%85%E5%90%8E%E4%BF%9D%E8%B4%B9%E9%87%8D%E6%96%B0%E5%8F%98%E8%B4%B5%22%7C%20PREM%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=B('<p><span class="marginnote">直觉类比：卖波动溢价像在压路机前弯腰捡钢镚——每次捡到的都是小钱（theta），压路机（崩盘）来时一次轧掉几年的积蓄。夏普高不是因为技术好，而是因为压路机还没来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不含事件窗内的专用打法，那是下一课；不含跨市场的价差，那是跨市场课；纯已实现波动的预测交易归预测栈与方差互换两课，不在此重复。所有案例都不给「必胜参数」：参数随状态变，写死参数等于把状态变量删掉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四个案例共享同一结构：把凸性保险卖给有结构性需求的人，收风险价格。</li><li>复盘四问：信号对齐哪条合同、溢价谁付、崩坏怎么来、记账怎么分列。</li><li>偏度与相关在崩盘重叠，两账必须正交化，防止溢价双计。</li><li>死法三部曲：拥挤、杠杆、体制切换；拥挤度是先导指标。</li><li>复盘必报三条：无条件夏普、条件最差月、拥挤度代理。</li><li>出处：Bakshi and Kapadia, 2003；Kozhan, Neuberger and Schneider, 2013；Driessen, Maenhout and Vilkov, 2009；恒等式见基础课。</li></ul>',5))])}const C=s(p,[["render",d]]);export{f as __pageData,C as default};
